class MyCalendarTwo {
    private final java.util.List<int[]> bookings = new java.util.ArrayList<>();
    private final java.util.List<int[]> overlaps = new java.util.ArrayList<>();

    public MyCalendarTwo() {
    }

    public boolean book(int start, int end) {
        for (int[] overlap : overlaps) {
            if (start < overlap[1] && overlap[0] < end) {
                return false;
            }
        }

        for (int[] booking : bookings) {
            int overlapStart = Math.max(start, booking[0]);
            int overlapEnd = Math.min(end, booking[1]);
            if (overlapStart < overlapEnd) {
                overlaps.add(new int[] {overlapStart, overlapEnd});
            }
        }

        bookings.add(new int[] {start, end});
        return true;
    }
}

class MyCalendarTwo {
    private final java.util.TreeMap<Integer, Integer> delta = new java.util.TreeMap<>();

    public MyCalendarTwo() {
    }

    public boolean book(int start, int end) {
        addDelta(start, 1);
        addDelta(end, -1);

        int active = 0;
        for (int change : delta.values()) {
            active += change;
            if (active >= 3) {
                addDelta(start, -1);
                addDelta(end, 1);
                return false;
            }
        }
        return true;
    }

    private void addDelta(int time, int change) {
        int next = delta.getOrDefault(time, 0) + change;
        if (next == 0) {
            delta.remove(time);
        } else {
            delta.put(time, next);
        }
    }
}

class MyCalendarTwo {
    private static class Node {
        Node left;
        Node right;
        int add;
        int max;
    }

    private final Node root = new Node();

    public MyCalendarTwo() {
    }

    public boolean book(int start, int end) {
        int left = start;
        int right = end - 1;
        if (query(root, 0, 1_000_000_000, left, right, 0) >= 2) {
            return false;
        }
        update(root, 0, 1_000_000_000, left, right, 1);
        return true;
    }

    private void update(Node node, int left, int right, int ql, int qr, int delta) {
        if (ql <= left && right <= qr) {
            node.add += delta;
            node.max += delta;
            return;
        }

        int mid = left + (right - left) / 2;
        if (ql <= mid) {
            if (node.left == null) {
                node.left = new Node();
            }
            update(node.left, left, mid, ql, qr, delta);
        }
        if (qr > mid) {
            if (node.right == null) {
                node.right = new Node();
            }
            update(node.right, mid + 1, right, ql, qr, delta);
        }

        int leftMax = node.left == null ? 0 : node.left.max;
        int rightMax = node.right == null ? 0 : node.right.max;
        node.max = node.add + Math.max(leftMax, rightMax);
    }

    private int query(Node node, int left, int right, int ql, int qr, int carry) {
        if (qr < left || right < ql) {
            return 0;
        }
        if (node == null) {
            return carry;
        }
        if (ql <= left && right <= qr) {
            return carry + node.max;
        }

        int mid = left + (right - left) / 2;
        int nextCarry = carry + node.add;
        return Math.max(
                query(node.left, left, mid, ql, qr, nextCarry),
                query(node.right, mid + 1, right, ql, qr, nextCarry));
    }
}

import java.util.*;

class MyCalendarTwo {
    private final ArrayList<int[]> bookings = new ArrayList<>();

    public MyCalendarTwo() {
    }

    public boolean book(int start, int end) {
        bookings.add(new int[] {start, end});

        TreeSet<Integer> points = new TreeSet<>();
        for (int[] booking : bookings) {
            points.add(booking[0]);
            points.add(booking[1]);
        }
        ArrayList<Integer> sortedPoints = new ArrayList<>(points);

        for (int i = 0; i + 1 < sortedPoints.size(); i++) {
            int segmentStart = sortedPoints.get(i);
            int segmentEnd = sortedPoints.get(i + 1);
            int active = 0;
            for (int[] booking : bookings) {
                if (booking[0] <= segmentStart && segmentEnd <= booking[1]) {
                    active++;
                }
            }
            if (active >= 3) {
                bookings.remove(bookings.size() - 1);
                return false;
            }
        }
        return true;
    }
}

class MyCalendarTwo {
    private final java.util.TreeMap<Integer, Integer> counts = new java.util.TreeMap<>();

    public MyCalendarTwo() {
        counts.put(0, 0);
        counts.put(1_000_000_000, 0);
    }

    public boolean book(int start, int end) {
        split(start);
        split(end);

        for (java.util.Map.Entry<Integer, Integer> entry = counts.ceilingEntry(start);
             entry != null && entry.getKey() < end;
             entry = counts.higherEntry(entry.getKey())) {
            if (entry.getValue() >= 2) {
                return false;
            }
        }

        for (java.util.Map.Entry<Integer, Integer> entry = counts.ceilingEntry(start);
             entry != null && entry.getKey() < end;
             entry = counts.higherEntry(entry.getKey())) {
            counts.put(entry.getKey(), entry.getValue() + 1);
        }
        return true;
    }

    private void split(int time) {
        java.util.Map.Entry<Integer, Integer> floor = counts.floorEntry(time);
        if (floor != null && floor.getKey() != time) {
            counts.put(time, floor.getValue());
        }
    }
}
